// Sender define o contrato que todo conector de canal precisa implementar
// para disparar uma notificação. Nenhum canal declara "implements Sender" —
// só precisa ter estes dois métodos.
type Sender interface {
	Send(ctx context.Context, n *Notification) error
	Channel() ChannelType
}

// Dispatcher processa uma notificação lida da fila.
type Dispatcher struct {
	Registry          *channel.Registry
	Repo              domain.Repository
	Limiters          *ratelimit.Limiters
	MaxBackoffSeconds int
}

func (r *Registry) Get(c domain.ChannelType) (Sender, error) {
	sender, ok := r.senders[c]
	if !ok {
		return nil, fmt.Errorf("nenhum conector registrado para o canal %q", c)
	}
	return sender, nil
}

