type Limiters struct {
	mu       sync.Mutex
	limiters map[domain.ChannelType]*rate.Limiter
	rps      map[domain.ChannelType]float64
}

func (l *Limiters) limiterFor(ch domain.ChannelType) *rate.Limiter {
	l.mu.Lock()
	defer l.mu.Unlock()

	if lim, ok := l.limiters[ch]; ok {
		return lim
	}
	rps := l.rps[ch]
	if rps <= 0 {
		rps = defaultRPS
	}
	lim := rate.NewLimiter(rate.Limit(rps), int(rps))
	l.limiters[ch] = lim
	return lim
}

transport := &http.Transport{
	DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, _ := net.SplitHostPort(addr)
		ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
		for _, ip := range ips {
			if isBlockedIP(ip) {
				return nil, fmt.Errorf("%w: %q resolve para endereço privado/interno (%s)", ErrBlockedTarget, host, ip)
			}
		}
		return dialer.DialContext(ctx, network, net.JoinHostPort(ips[0].String(), port))
	},
}

func NextBackoff(attempt int, maxSeconds int) time.Duration {
	capSeconds := 1 << attempt // 2^attempt
	if capSeconds <= 0 || capSeconds > maxSeconds {
		capSeconds = maxSeconds
	}
	jittered := 1 + rand.Intn(capSeconds)
	return time.Duration(jittered) * time.Second
}

const pqUniqueViolation = "23505"

func (r *NotificationRepository) Create(ctx context.Context, n *domain.Notification) error {
	payload, _ := json.Marshal(orEmptyMap(n.Payload))
	_, err := r.conn.ExecContext(ctx, `
		INSERT INTO notifications (id, channel, target, message, payload, status, ...)
		VALUES ($1, $2, $3, $4, $5, $6, ...)`,
		n.ID, n.Channel, n.Target, n.Message, payload, n.Status)

	if pqErr, ok := err.(*pq.Error); ok && pqErr.Code == pqUniqueViolation {
		return domain.ErrDuplicateIdempotencyKey
	}
	return err
}
